SELECT t0.name AS "Name",t1.name AS "Parent Name" FROM (SELECT t2.unit_id AS "unit_id",t2.name AS "name",t2.parent_id AS "parent_id" FROM org.units AS t2 WHERE t2.active = 1) AS t0 LEFT OUTER JOIN (SELECT t3.unit_id AS "unit_id",t3.name AS "name",t3.parent_id AS "parent_id" FROM org.units AS t3 WHERE t3.active = 1) AS t1 ON (t1.unit_id = t0.parent_id) ORDER BY t0.unit_id ASC NULLS FIRST
